<template><view class="conj-practice"><view class="practice-top"><button class="icon-button back-control" hover-class="none" @click="$emit('close')" aria-label="返回 / Retour"><Icon name="back"/></button><view class="practice-location"><Bi zh="变位练习" fr="Conjugaison" small/><text class="muted">{{ groupLabel }}</text></view><text class="practice-count">{{ completedVerbs }} / {{ verbTotal }}</text></view>
 <view v-if="(state.done||state.paused)&&!feedback&&!locked" class="completion glass conj-complete"><view class="completion-icon"><Icon name="check"/></view><Bi :zh="state.done?'变位练习完成':'本组完成'" :fr="state.done?'Terminé':'Série terminée'"/><view class="completion-actions"><button class="button secondary" hover-class="none" @click="$emit('close')"><Bi zh="返回" fr="Retour" small/></button><button v-if="!state.done" class="button primary" hover-class="none" @click="$emit('continue')"><Bi zh="继续练习" fr="Continuer" small/></button></view></view>
 <template v-else-if="q"><view class="conj-practice-scroll"><view class="conj-batch"><view v-for="e in batchVerbs" :key="e.verbe+'|'+e.temps" class="conj-verb"><text lang="fr">{{ e.verbe }}</text><text class="conj-batch-meaning">{{ e.meaning }}</text><text class="conj-batch-tense">{{ e.temps }}</text></view></view><Bi :zh="q.round==='match'?'人称与变位配对':'写出对应变位'" :fr="q.round==='match'?'Associer':'Écrire la forme'" small/>
 <view v-if="q.round==='match'" class="conj-match-grid"><button v-for="token in layout" :key="token.side+token.key" hover-class="none" :class="['conj-match-card','card-'+token.side,{selected:chosen[token.side]===token.key,cleared:gone(token),correct:flash?.correct&&flash[token.side]===token.key,incorrect:flash&&!flash.correct&&flash[token.side]===token.key}]" :disabled="busy||locked||gone(token)" @click="choose(token)"><text lang="fr">{{ token.side==='left'?(q.board.left_persons?.[token.key]||cards[token.key].personne):cards[token.key].form }}</text></button></view>
 <view v-else class="glass conj-fill"><view class="conj-fill-heading"><text class="conj-fill-verb" lang="fr">{{ q.verbe }}</text><text class="conj-fill-meaning">{{ meaningFor(q.verbe) }}</text></view><text class="muted">{{ q.temps }}</text><view :class="['exercise-entry',{correct:feedback?.correct,incorrect:feedback&&!feedback.correct}]" @click="retry"><text class="given-article">{{ personPrefix }}</text><AnswerInput ref="field" v-model="input" :touch="touch" :active="keyboard" :disabled="busy||locked||!!feedback" @activate="openKeyboard" @keydown="enter"/><Icon v-if="feedback" :name="feedback.correct?'check':'close'"/></view><view v-if="feedback" :class="['spelling-result',{correct:feedback.correct}]" role="status"><Icon :name="feedback.correct?'check':'repeat'"/><Bi :zh="feedback.correct?'正确':'再试一次'" :fr="feedback.correct?'Correct':'À revoir'" small/></view><SpellingFeedback v-if="feedback&&(!feedback.correct||feedback.fuzzy)" :diff="diff"/></view>
 </view><view class="exercise-footer"><button v-if="q.round!=='fill'||feedback" class="button secondary conj-definition-button" hover-class="none" :disabled="busy||locked" @click="showDefinition"><Icon name="book"/><Bi zh="释义" fr="Fiche" small/></button><template v-if="q.round==='fill'"><button v-if="feedback?.correct" class="button primary" hover-class="none" :disabled="busy||locked" @click="continueFill"><Bi zh="继续" fr="Continuer" small/><Icon name="arrow"/></button><button v-else-if="feedback" class="button primary" hover-class="none" :disabled="busy||locked" @click="retry"><Icon name="repeat"/><Bi zh="重试" fr="Réessayer" small/></button><button v-else class="button primary" hover-class="none" :disabled="busy||locked||!input.trim()" @click="submit"><Bi zh="提交" fr="Valider" small/><Icon name="check"/></button></template><Bi v-else zh="先选人称，再选变位" fr="Associez une personne et une forme." small/></view>
 </template><Transition name="page-fade"><ConjugationDetails v-if="inspecting" :word="inspecting" @close="inspecting=null" @audio="$emit('audio',$event)"/></Transition><Teleport to="body"><FrenchKeyboard v-if="touch&&keyboard&&!feedback&&q?.round==='fill'&&!state.done&&!state.paused&&!inspecting" :disabled="busy||locked||!input.trim()" @input="insert" @delete="erase" @confirm="submit" @close="closeKeyboard"/></Teleport></view></template>
<script setup>
import {computed,ref,watch,onUnmounted} from 'vue';import Bi from './Bi.vue';import Icon from './Icon.vue';import AnswerInput from './AnswerInput.vue';import FrenchKeyboard from './FrenchKeyboard.vue';import SpellingFeedback from './SpellingFeedback.vue';import ConjugationDetails from './ConjugationDetails.vue';import {cardLayout} from '../conjugation/card-layout.js';import {recording,spokenForm} from '../conjugation/catalog.js';import {spellingDiff} from '../domain/spelling-diff.js';import {playCorrect,playTap} from '../platform/feedback-sounds.js';
const props=defineProps({state:Object,busy:Boolean});const emit=defineEmits(['close','answer','continue','audio']);const chosen=ref({}),flash=ref(null),locked=ref(false),input=ref(''),feedback=ref(null),field=ref(null),keyboard=ref(false),inspecting=ref(null);let timer;
const touch=/Android|iPhone|iPad/i.test(navigator.userAgent),q=computed(()=>props.state.viewQuestion),layout=computed(()=>q.value?.board?cardLayout(q.value.board):[]),cards=computed(()=>Object.fromEntries((q.value?.board?.cards||[]).map(c=>[c.key,c]))),batchVerbs=computed(()=>[...new Map((props.state.engine.groups[(q.value?.batch_index||props.state.engine.cursor+1)-1]?.entries||[]).map(e=>[e.verbe,e])).values()]),verbTotal=computed(()=>new Set(props.state.engine.groups.flatMap(g=>g.entries.map(e=>e.verbe+'|'+e.temps))).size),completedVerbs=computed(()=>props.state.engine.completed_words.length),groupLabel=computed(()=>`第 ${q.value?.batch_index||Math.min(props.state.engine.cursor+1,props.state.engine.groups.length)} / ${props.state.engine.groups.length} 组 · Séries`),diff=computed(()=>feedback.value?spellingDiff(feedback.value.input,feedback.value.expected):[]);
const meaningFor=verb=>props.state.engine.groups.flatMap(g=>g.entries).find(e=>e.verbe===verb&&e.temps===q.value?.temps)?.meaning||'';
const personPrefix=computed(()=>q.value?.personne==='je'&&spokenForm(q.value.verbe,q.value.temps,'je').startsWith('j’')?"j’":q.value?.personne);
const gone=t=>q.value.board['matched_'+t.side].includes(t.key);
function inspect(e){const tense=props.state.engine.entries.some(item=>item.verbe===e.verbe&&item.temps===q.value?.temps)?q.value.temps:e.temps;inspecting.value={conjugation:{lemma:e.verbe,tense}};}
function showDefinition(){if(!q.value||props.busy||locked.value||(q.value.round==='fill'&&!feedback.value))return;closeKeyboard();inspect({verbe:q.value.verbe,temps:q.value.temps});}
function send(body,selection){locked.value=true;emit('answer',{id:q.value.id,...body},result=>{if(!result){locked.value=false;return;}if(result.correct){playCorrect();const phrase=result.spoken;if(phrase)emit('audio',recording(phrase));}flash.value=selection?{...selection,correct:result.correct}:null;feedback.value=result;if(!selection){locked.value=false;closeKeyboard();return;}timer=setTimeout(()=>{chosen.value={};flash.value=null;locked.value=false;input.value='';feedback.value=null;emit('continue',true);},result.correct?130:300);});}
function choose(t){if(locked.value||props.busy)return;chosen.value={...chosen.value,[t.side]:chosen.value[t.side]===t.key?null:t.key};if(chosen.value.left&&chosen.value.right)send({person_key:chosen.value.left,form_key:chosen.value.right},{...chosen.value});}
function continueFill(){if(props.busy||locked.value||!feedback.value?.correct)return;feedback.value=null;input.value='';emit('continue',true);}
function submit(){if(locked.value||props.busy||feedback.value||!input.value.trim())return;closeKeyboard();send({answer:field.value?.element?.value??input.value});}
function openKeyboard(){if(!touch||props.busy||locked.value||feedback.value||q.value?.round!=='fill')return;keyboard.value=true;field.value?.focus();}
function closeKeyboard(){keyboard.value=false;field.value?.blur();}
function retry(){if(props.busy||locked.value||feedback.value?.correct)return;if(feedback.value&&!feedback.value.correct){feedback.value=null;input.value='';}openKeyboard();}
function insert(text){if(!props.busy&&!locked.value)field.value?.replaceRange(text);}
function erase(){if(!props.busy&&!locked.value)field.value?.replaceRange('',true);}
function enter(e){
 if(e.isComposing||e.keyCode===229)return;
 if(e.key==='Enter'){e.preventDefault();e.stopPropagation();submit();return;}
 if(!touch||e.ctrlKey||e.metaKey||e.altKey)return;
 if(e.key==='Escape'){e.preventDefault();e.stopPropagation();closeKeyboard();}
 else if(e.key==='Backspace'||e.key==='Delete'){e.preventDefault();e.stopPropagation();if(!props.busy&&!locked.value){playTap();field.value?.replaceRange('',e.key==='Backspace',e.key==='Delete');}}
 else if(e.key?.length===1){e.preventDefault();e.stopPropagation();playTap();insert(e.key);}
}
watch(()=>q.value?[q.value.verbe,q.value.temps,q.value.personne,q.value.round,q.value.board?.id].join('|'):'',()=>{if(!locked.value){input.value='';feedback.value=null;chosen.value={};}});watch(input,()=>{if(input.value&&feedback.value&&!feedback.value.correct){feedback.value=null;}});onUnmounted(()=>{clearTimeout(timer);});
</script>
<style scoped>.conj-practice{display:flex;flex-direction:column;min-height:0;flex:1;height:100%;gap:12px}.conj-practice-scroll{min-height:0;flex:1;overflow-y:auto;padding:2px}.conj-batch{display:flex;gap:8px;margin:5px 0 18px}.conj-verb{display:flex;align-items:center;flex-wrap:wrap;gap:5px;flex:1;min-width:0;padding:10px;border:1px solid #dbe4f0;border-radius:13px;background:#f5f8fe}.conj-verb>text:first-child{font:18px/1.5 Georgia,serif;width:100%;color:#587296;overflow-wrap:anywhere}.conj-match-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:9px;margin-top:14px}.conj-match-card{min-width:0;min-height:64px;padding:11px 6px;border:1px solid #ccd9ec;border-radius:14px;background:#fff;font:18px/1.5 Georgia,serif;text-align:center;color:#526f96;overflow-wrap:anywhere}.card-right{background:#edf3fb}.conj-match-card{transition:background-color .08s,border-color .08s,transform .08s}.conj-match-card.selected{background:#e1eafb;border-color:#8ea9d1}.conj-match-card.correct{background:#e2f2e8;border-color:#94bba4}.conj-match-card.incorrect{background:#f9e8ed;border-color:#dba8b2}.conj-match-card.cleared{visibility:hidden}.conj-fill{padding:23px 18px;margin:16px 0}.conj-fill-verb{display:block;font:30px/1.5 Georgia,serif;color:#526b91}.conj-fill .exercise-entry{margin-top:23px}.conj-complete{margin:auto 0}.conj-practice .exercise-footer{flex-shrink:0}.conj-practice .exercise-footer>.button{flex:1;min-width:0;padding:10px 9px;gap:7px}.conj-definition-button .icon{width:17px;height:17px}.conj-fill .given-article{font-size:22px;padding-right:12px}@media(max-height:650px){.conj-match-card{min-height:51px;font-size:16px}.conj-batch{margin-bottom:11px}}.conj-fill-heading{display:flex;align-items:baseline;gap:12px;flex-wrap:wrap}.conj-fill-meaning{font-size:13px;color:#8a9bb3;line-height:1.6}
.conj-verb>.conj-batch-meaning{font-size:12px;line-height:1.5;width:100%;color:#7387a6}.conj-verb>.conj-batch-tense{font-size:9px;color:#9cabc1}</style>
